      "document": "query MatchConnection($testId: ID!, $nextPageCursor: Int, $sortType: DnaMatchesSortValues, $limit: Int!, $matchDistance: MatchDistance, $treeFilter: TreeFilter, $searchPhonetic: Boolean, $customGroupIds: [String], $searchDisplayName: String, $searchGpid: String, $searchSurname: String, $minSharedDna: Int, $maxSharedDna: Int, $paternalId: String, $maternalId: String, $relationSampleId: String, $notes: Boolean, $notViewed: Boolean, $newMatches: Boolean, $messaged: Boolean, $ignored: Boolean, $starred: Boolean, $commonAncestors: Boolean, $parentalFilter: MatchesParentalFilter) { dnaTest(testId: $testId) { matches { matchConnection(nextPageCursor: $nextPageCursor, sortType: $sortType, limit: $limit, matchDistance: $matchDistance, treeFilter: $treeFilter, searchPhonetic: $searchPhonetic, customGroupIds: $customGroupIds, searchDisplayName: $searchDisplayName, searchGpid: $searchGpid, searchSurname: $searchSurname, minSharedDna: $minSharedDna, maxSharedDna: $maxSharedDna, paternalId: $paternalId, maternalId: $maternalId, relationSampleId: $relationSampleId, notes: $notes, notViewed: $notViewed, newMatches: $newMatches, messaged: $messaged, ignored: $ignored, starred: $starred, commonAncestors: $commonAncestors, parentalFilter: $parentalFilter) { nodes { hasCommonAncestors testId kinshipLabel relationshipLabel meiosisLabel note starred ignored viewed gender mothersSide fathersSide subjectIsAdmin subjectIsCurrentUser profile { userId displayName publicDisplayName displayInitials photoUrl } adminProfile { userId displayName displayInitials } access { isGuest isOwner isAdmin isEditor } relationship { sharedCentimorgans meiosis sharedSegments confidence percentShared upperBoundPercentShared } autoCluster treeInfo { matchTestId treeId treeSize unlinkedTree noTrees privateTree publicTree isSearchable treeUnavailable } customTags { color label tagId } matchGroupLabel } pageInfo { total nextPageCursor hasNextPage } } } } }",
